import random, itertools, sys
import networkx as nx
n=25
def girth(G):
    # return length of shortest cycle or large
    try:
        return nx.algorithms.cycles.minimum_cycle_basis(G, weight=None)
    except Exception:
        return None

def shortest_cycle_length(G):
    # brute BFS from each node
    minlen=10**9
    for start in G.nodes():
        # BFS
        visited={start:0}
        parent={start:None}
        queue=[start]
        while queue:
            v=queue.pop(0)
            for w in G.neighbors(v):
                if w not in visited:
                    visited[w]=visited[v]+1
                    parent[w]=v
                    queue.append(w)
                elif parent[v]!=w: # found cycle
                    length=visited[v]+visited[w]+1
                    if length<minlen:
                        minlen=length
        if minlen==3:
            break
    return minlen if minlen!=10**9 else None

def try_random(trials=10000):
    for _ in range(trials):
        G=nx.Graph()
        G.add_nodes_from(range(n))
        # ensure degree between 3 and 6
        # start with random regular degree 3 maybe then add edges
        # generate random 3-regular then add edges up to 6 while avoiding short cycles
        # use configuration model
        deg=[3]*n
        # adjust to make sum even
        stubs=[]
        for v,d in enumerate(deg):
            stubs+= [v]*d
        random.shuffle(stubs)
        while stubs:
            a=stubs.pop()
            b=stubs.pop()
            if a==b or G.has_edge(a,b):
                # restart
                break
            G.add_edge(a,b)
        else:
            # succeeded 3-regular
            # now try adding edges
            possible=[(i,j) for i in range(n) for j in range(i+1,n) if not G.has_edge(i,j)]
            random.shuffle(possible)
            for (i,j) in possible:
                if G.degree[i]>=6 or G.degree[j]>=6:
                    continue
                G.add_edge(i,j)
                if shortest_cycle_length(G) is not None and shortest_cycle_length(G)<7:
                    G.remove_edge(i,j)
            if all(3<=G.degree[v]<=6 for v in G.nodes()):
                if shortest_cycle_length(G) is None or shortest_cycle_length(G)>=7:
                    return G
    return None
